import { openDB } from "idb";

// Save data to IndexedDB
export async function saveSubmission(token, answers) {
  const db = await openDB("exam-db", 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains("exam-data")) {
        db.createObjectStore("exam-data", { keyPath: "token" });
      }
    },
  });

  await db.put("exam-data", { token, answers });
  console.log("Data saved to IndexedDB for token:", token);
}

// Fetch all submissions from IndexedDB
export async function getAllExamData() {
  const db = await openDB("exam-db", 1);
  return db.getAll("exam-data");
}

// Sync data immediately
export async function syncSubmissions() {
  const data = await getAllExamData();
  console.log("Syncing submissions:", data);
  return data;
}

