function register() {
  if ('serviceWorker' in navigator) {
    console.log("Inside the register function");

    // Check if a service worker is already controlling the page
    if (navigator.serviceWorker.controller) {
      console.log('Service Worker is already controlling the page');
      return; // If a service worker is already active, no need to register a new one
    }

    // Register the service worker
    navigator.serviceWorker
      .register('/sw.js') // Correct path (relative to domain root)
      .then((registration) => {
        console.log('Service Worker registered with scope:', registration.scope);

        // Optionally, listen for updates to the service worker and update it if needed
        registration.onupdatefound = () => {
          const installingWorker = registration.installing;
          installingWorker.onstatechange = () => {
            if (installingWorker.state === 'installed') {
              if (navigator.serviceWorker.controller) {
                console.log('New content is available and will be used when all tabs for this page are closed.');
              } else {
                console.log('Content is cached for offline use.');
              }
            }
          };
        };

        // Check if background sync is supported
        if ('SyncManager' in window) {
          console.log('Background sync is supported');
        }
      })
      .catch((error) => {
        console.error('Service Worker registration failed:', error);
      });
  } else {
    console.error('Service Worker is not supported in this browser.');
  }
}



